<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue';defineProps<{title:string}>();const emit=defineEmits(['close']);const panel=ref<HTMLElement>();let previous:Element|null=null;function key(e:KeyboardEvent){if(e.key==='Escape')emit('close');if(e.key==='Tab'){const els=panel.value?.querySelectorAll<HTMLElement>('button,input,select,textarea,a[href]');if(!els?.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}onMounted(()=>{previous=document.activeElement;panel.value?.focus();document.addEventListener('keydown',key);});onBeforeUnmount(()=>{document.removeEventListener('keydown',key);if(previous instanceof HTMLElement)previous.focus();});
</script>
<template><Teleport to="body"><div class="modal-backdrop" @click.self="emit('close')"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1" ref="panel"><div class="modal-heading"><h2 id="modal-title">{{title}}</h2><button class="icon-button" aria-label="Cerrar" @click="emit('close')">×</button></div><slot/></section></div></Teleport></template>
